//! Replays the oracle corpus: every case under `fixtures/oracle/` must get,
//! from this crate, the answer upstream's TypeScript gave, compared as text.
//!
//! The corpus is regenerated by `tools/oracle/refresh.sh`; nothing here needs
//! upstream or Bun to be present.

mod common;

use std::fs;

use focus_graph::oracle::run_case;
use focus_js::json::stringify;
use serde_json::{Value, json};

#[test]
fn every_case_gets_upstreams_answer() {
    let dir = common::fixtures().join("oracle");
    let cases = fs::read_to_string(dir.join("cases.ndjson")).unwrap();
    let expected = fs::read_to_string(dir.join("expected.ndjson")).unwrap();
    let cases: Vec<&str> = cases.lines().filter(|l| !l.is_empty()).collect();
    let expected: Vec<&str> = expected.lines().filter(|l| !l.is_empty()).collect();
    assert_eq!(
        cases.len(),
        expected.len(),
        "cases.ndjson and expected.ndjson are out of step"
    );
    assert!(
        cases.len() > 1000,
        "corpus is unexpectedly small: {}",
        cases.len()
    );

    let mut differing = Vec::new();
    let mut declined = 0;
    for (line, want) in cases.iter().zip(&expected) {
        // Parsed as upstream's driver parses it, so nested objects are in the
        // order a JS object enumerates them.
        let case: Value = focus_js::json::parse(line).unwrap();
        // Other kinds are replayed by the crate that answers them.
        if !focus_graph::oracle::KINDS.contains(&case["kind"].as_str().unwrap_or_default()) {
            continue;
        }
        let answer = run_case(&case);
        let got = stringify(&json!({ "id": case["id"], "out": answer }));
        // A memory file with Markdown focus has no parser for may be declined
        // instead of answered. Nothing else may.
        if case["kind"] == "guardwild" && answer.get("refused").is_some() {
            declined += 1;
            continue;
        }
        if got != *want {
            differing.push(format!(
                "{}\n  upstream: {want}\n  focus:    {got}",
                case["id"]
            ));
        }
    }
    let wild = cases
        .iter()
        .filter(|l| l.contains("\"kind\": \"guardwild\""))
        .count();
    assert!(
        declined * 10 < wild * 9,
        "focus declined {declined} of {wild} guardwild cases; the reader is refusing too much to prove anything"
    );
    assert!(
        differing.is_empty(),
        "{} of {} cases differ from upstream; first:\n{}",
        differing.len(),
        cases.len(),
        differing
            .iter()
            .take(3)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}

#[test]
fn the_corpus_exercises_every_kind_and_both_outcomes() {
    // A corpus of nothing but refusals, or nothing but acceptances, would
    // pass the replay while proving little.
    let expected = fs::read_to_string(common::fixtures().join("oracle/expected.ndjson")).unwrap();
    let count = |needle: &str| expected.lines().filter(|l| l.contains(needle)).count();
    for kind in [
        "stage-",
        "sensor-",
        "rule-",
        "scalar-",
        "list-",
        "collate-",
        "num-",
        "cycles-",
        "record-",
        "foldback-",
        "settings-",
        "guard-",
        "guardwild-",
    ] {
        assert!(
            count(&format!("{{\"id\":\"{kind}")) > 100,
            "too few {kind} cases"
        );
    }
    // The memory reader has to be seen finding declarations and finding none.
    assert!(count("\"out\":{\"heading\":\"## Guard Policy\"") > 50);
    assert!(count("\"out\":{\"heading\":\"## Change Control\"") > 5);
    assert!(count("\"out\":{\"heading\":null") > 50);
    assert!(count("\"valid\":true") > 100);
    assert!(count("\"valid\":false") > 100);
    assert!(count("\"out\":{\"error\":") > 10);
}
